import {APP_DATE,COLORS,TYPES,OH_TASK_CATALOG,OH_GROUPS,OH_COLORS,DEFAULT_SETTINGS,FLAG_NAMES,norm,txt,iso,utc,addDays,weekKey,dateLabel,monthLabel,sum,ratio,buildDataset,emptyFilters,analyze,groupFacts,trend,defaultFilters,csvText,parseWorkbook,classify,taskKey,statusFor,STATUS_COLORS} from './engine.js';
import {esc,num,pct,hrs,short,icon,filterAttrs,emptyChart,hbars,donut,trendChart,disciplineChart,stackedBars,statusBadge,occupancyHeatmap,matrix} from './charts.js';

const app=document.getElementById('app'),overlay=document.getElementById('overlay-root');
const VIEWS={overview:['Visión general','Análisis histórico de las horas registradas en proyectos y Overhead.','overview'],capacity:['Comparación mensual','Compara las horas registradas y su distribución entre períodos.','capacity'],projects:['Inteligencia de proyectos','Entiende qué proyectos concentraron las horas y cómo participa cada disciplina.','projects'],oh:['Overhead Intelligence','Analiza las horas de OH según las categorías y Tasks del catálogo ME&I.','oh'],team:['Detalle del equipo','Explora las horas registradas y el contexto de cada colaborador.','team'],work:['Desglose del trabajo','Descubre qué actividades, Tasks y especialidades consumen las horas.','work'],quality:['Calidad de datos','Revisa la trazabilidad y los registros que necesitan atención.','quality'],data:['Centro de datos','Actualiza el seguimiento y conserva el control sobre tu análisis.','data']};
const state={view:VIEWS[location.hash.slice(1)]?location.hash.slice(1):'overview',raw:null,original:null,dataset:null,model:null,settings:structuredClone(DEFAULT_SETTINGS),filters:emptyFilters(),more:false,openFilter:null,exportOpen:false,mobile:false,grain:'week',series:['project','oh'],tables:{},modal:null,pendingImport:null};
const safeStore={get(k){try{return JSON.parse(localStorage.getItem(k));}catch{return null;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}};
let searchTimer,toastTimer,modalReturnFocus;

async function localSource(action,value){return new Promise((resolve,reject)=>{const req=indexedDB.open('mei-intelligence',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('data',action==='get'?'readonly':'readwrite'),store=tx.objectStore('data'),op=action==='get'?store.get('source'):action==='delete'?store.delete('source'):store.put(value,'source');let result;op.onsuccess=()=>result=op.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)};};});}
function toast(message,error=false){const el=document.getElementById('toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4500);}
function rebuild(raw){state.raw=raw;state.dataset=buildDataset(raw,state.settings);}
function currentModel(){state.filters.status=[];state.filters.ohGroup=state.filters.ohGroup.filter(g=>OH_GROUPS.includes(g));return analyze(state.dataset,state.view==='capacity'?{...state.filters,months:[],weeks:[],from:'',to:''}:state.filters,state.settings);}
function saveContext(){safeStore.set('mei-context-v1',{view:state.view,filters:state.filters,filename:state.raw.filename});}
function activeFilterCount(){const f=state.filters;return ['fy','months','weeks','discipline','role','person','project','type','category','ohGroup','task'].reduce((n,k)=>n+(f[k].length?1:0),0)+(f.search?1:0)+(f.flag?1:0)+(f.from?1:0)+(f.to&&f.to!==state.settings.cutoff?1:0);}
function initials(name){return txt(name).replace(',',' ').split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('');}
function pageContext(){const dates=state.model.dates;return dates.length?`${dateLabel(dates[0],{day:'numeric',month:'short',year:'numeric'})} a ${dateLabel(dates.at(-1),{day:'numeric',month:'short',year:'numeric'})}`:'Sin fechas en el contexto';}
function card(title,subtitle,body,{tools='',footer='',className=''}={}){return `<section class="card ${className}"><div class="card-header"><div><h2 class="card-title">${title}</h2>${subtitle?`<p class="card-subtitle">${subtitle}</p>`:''}</div>${tools?`<div class="card-tools">${tools}</div>`:''}</div><div class="card-body">${body}</div>${footer?`<div class="card-footer">${footer}</div>`:''}</section>`;}
function kpi(label,value,{unit='',note='',glyph='clock',tone='',accent=false}={}){return `<article class="kpi-card"><div class="kpi-top"><span class="kpi-label">${label}</span><span class="kpi-icon ${tone}">${icon(glyph,14)}</span></div><div class="kpi-value">${value}${unit?`<span class="unit">${unit}</span>`:''}</div><p class="kpi-foot">${note||'&nbsp;'}</p>${accent?'<span class="kpi-accent"></span>':''}</article>`;}
function kpiGrid(items,cls=''){return `<div class="kpi-grid ${cls}">${items.join('')}</div>`;}
function grainControl(){return `<div class="segmented" aria-label="Agrupación temporal">${[['week','Semana'],['month','Mes'],['day','Día']].map(([g,n])=>`<button data-action="grain" data-value="${g}" class="${state.grain===g?'active':''}" aria-pressed="${state.grain===g}">${n}</button>`).join('')}</div>`;}
function infoButton(topic='method'){return `<button class="icon-button" data-action="${topic}" aria-label="Ver metodología" title="Ver metodología">${icon('info',14)}</button>`;}

function options(key){const d=state.dataset;let values=[];
  if(key==='months')values=[...new Set(d.records.map(r=>r.month))].sort().map(v=>({value:v,label:monthLabel(v)}));
  else if(key==='weeks')values=[...new Set(d.personDays.map(r=>r.week))].sort().map(v=>({value:v,label:`${dateLabel(v)} – ${dateLabel(addDays(v,6),{day:'numeric',month:'short',year:'numeric'})}`}));
  else if(key==='person')values=d.people.map(p=>({value:p.person,label:p.name}));
  else if(key==='project')values=[...new Map(d.records.filter(r=>r.type==='Proyecto').map(r=>[r.projectKey,{value:r.projectKey,label:r.project+(r.code?' · '+r.code:' · sin código')}])).values()].sort((a,b)=>a.label.localeCompare(b.label,'es'));
  else if(key==='type')values=TYPES.map(v=>({value:v,label:v}));
  else if(key==='task')values=[...new Set(d.records.map(r=>r.task))].sort((a,b)=>a.localeCompare(b,'es')).map(v=>({value:v,label:v||'Sin Task'}));
  else if(key==='ohGroup')values=OH_GROUPS.map(v=>({value:v,label:v}));
  else values=[...new Set((['discipline','role'].includes(key)?d.personDays:d.records).map(r=>r[key]))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'es')).map(v=>({value:v,label:v}));
  return values;
}
const FILTER_LABELS={fy:'Año fiscal de fuente',months:'Mes',weeks:'Semana del lunes',discipline:'Disciplina',role:'Rol',person:'Colaborador',project:'Proyecto',type:'Tipo de hora',category:'Categoría de trabajo',ohGroup:'Categoría OH',task:'Task'};
function filter(key,wide=false){const opts=options(key),selected=state.filters[key],label=selected.length===1?(opts.find(o=>o.value===selected[0])?.label||selected[0]):selected.length>1?`${selected.length} seleccionados`:key==='months'?'Todos los meses':key==='project'?'Todos los proyectos':key==='person'?'Todo el equipo':key==='weeks'?'Todas las semanas':'Todos';return `<div class="filter-item ${wide?'filter-wide':''}"><span class="filter-label" id="label-${key}">${FILTER_LABELS[key]}</span><button class="filter-trigger ${selected.length?'has-value':''}" data-action="open-filter" data-key="${key}" aria-labelledby="label-${key}" aria-expanded="${state.openFilter===key}"><span>${esc(label)}</span>${icon('chevron',12)}</button>${state.openFilter===key?`<div class="filter-popover" data-popover="${key}"><input type="search" placeholder="Buscar ${FILTER_LABELS[key].toLowerCase()}…" data-option-search="${key}" aria-label="Buscar opciones de ${FILTER_LABELS[key]}" autocomplete="off"><div class="filter-options">${opts.map(o=>`<label class="filter-option" data-option-text="${esc(norm(o.label))}"><input type="checkbox" data-filter-key="${key}" value="${esc(o.value)}" ${selected.includes(o.value)?'checked':''}><span>${esc(o.label)}</span></label>`).join('')||'<div class="no-matches">Sin opciones disponibles</div>'}</div><div class="filter-popover-footer"><button class="text-link" data-action="clear-filter" data-key="${key}">Limpiar selección</button><button class="text-link" data-action="close-filter">Aplicar ${icon('check',11)}</button></div></div>`:''}</div>`;}
function filtersPanel(){
  const f=state.filters,extras=['fy','weeks','person','type','category','ohGroup','task'];
  const chips=[];for(const key of ['months','weeks','discipline','role','person','project','type','category','ohGroup','task']){for(const v of f[key]){const label=options(key).find(o=>o.value===v)?.label||v;chips.push(`<span class="chip" title="${esc(FILTER_LABELS[key]+': '+label)}"><span>${esc(label)}</span><button data-action="remove-filter" data-key="${key}" data-value="${esc(v)}" aria-label="Quitar filtro ${esc(label)}">×</button></span>`);}}
  if(f.flag)chips.push(`<span class="chip"><span>${esc(FLAG_NAMES[f.flag])}</span><button data-action="clear-flag" aria-label="Quitar filtro de calidad">×</button></span>`);
  return `<section class="filter-panel" aria-label="Filtros del análisis"><div class="filter-row">${filter('months')}${filter('discipline')}${filter('role')}${filter('project',true)}<div class="filter-extra"><button class="button" data-action="more-filters" aria-expanded="${state.more}">${icon('filter',13)}Filtros${activeFilterCount()?`<span class="count">${activeFilterCount()}</span>`:''}</button><button class="icon-button" data-action="reset-filters" title="Restablecer filtros" aria-label="Restablecer filtros">${icon('reset',14)}</button></div></div>${state.more?`<div class="more-filters">${extras.map(k=>filter(k)).join('')}<div><label class="filter-label" for="date-from">Desde</label><input id="date-from" class="date-input" type="date" value="${esc(f.from)}" data-date-filter="from"></div><div><label class="filter-label" for="date-to">Hasta</label><input id="date-to" class="date-input" type="date" value="${esc(f.to)}" data-date-filter="to"></div><div class="search-control"><label class="filter-label" for="global-search">Buscar en proyectos, personas, Tasks y comentarios</label>${icon('search',14)}<input id="global-search" class="date-input" type="search" placeholder="Escribe para explorar los registros…" value="${esc(f.search)}" autocomplete="off"></div><div style="grid-column:1/-1;display:flex;gap:7px;flex-wrap:wrap"><button class="button small" data-action="period" data-value="complete">Último mes anterior</button><button class="button small" data-action="period" data-value="cutoff">Todo hasta el corte</button><button class="button small" data-action="period" data-value="all">Todo el archivo</button></div></div>`:''}<div class="filter-footer"><span class="context-label">${icon('calendar',12)}<span>${esc(pageContext())} <span style="color:#bcc7cb">/</span> ${num(state.model.facts.length)} registros diarios</span></span><button class="text-link" data-action="method" title="Consulta las definiciones de los indicadores históricos">${icon('info',12)}</button></div>${chips.length?`<div class="filter-chips">${chips.join('')}</div>`:''}</section>`;
}
function render({focus=null,selection=null}={}){
  state.model=currentModel();const m=state.model,[title,subtitle]=VIEWS[state.view];saveContext();
  const nav=(key,label)=>`<button class="nav-item ${state.view===key?'active':''}" data-action="nav" data-value="${key}" ${state.view===key?'aria-current="page"':''}>${icon(VIEWS[key][2],17)}<span>${label}</span>${key==='quality'&&state.dataset.issues.length?`<span class="nav-count">${state.dataset.issues.length}</span>`:''}</button>`;
  app.innerHTML=`<div class="mobile-backdrop ${state.mobile?'show':''}" data-action="mobile-close"></div><aside class="sidebar ${state.mobile?'open':''}" aria-label="Navegación principal"><div class="brand"><div class="brand-name">ME<span>&</span>I</div><div class="brand-subtitle">Intelligence portal</div></div><div class="nav-section">ESPACIO DE ANÁLISIS</div><nav>${nav('overview','Visión general')}${nav('capacity','Comparación mensual')}${nav('projects','Proyectos')}${nav('oh','Overhead Intelligence')}${nav('team','Equipo y personas')}${nav('work','Desglose del trabajo')}</nav><div class="nav-section">ADMINISTRACIÓN</div><nav>${nav('quality','Calidad de datos')}${nav('data','Centro de datos')}<button class="nav-item" data-action="settings">${icon('settings',17)}<span>Configuración</span></button></nav><div class="sidebar-spacer"></div><button class="nav-item" data-action="method">${icon('help',17)}<span>Guía de interpretación</span></button><div class="sidebar-source"><div class="source-online"><span class="dot"></span>${!state.usingLocal?'Datos del seguimiento':'Copia local actualizada'}</div><strong title="${esc(state.raw.filename)}">${esc(state.raw.filename)}</strong><small>${num(state.dataset.records.length)} registros · ${state.dataset.sourceSheets.length} hojas mensuales</small></div><div class="sidebar-bottom"><span class="aecom">AECOM</span><span>ENTERPRISE CAPABILITIES</span></div></aside><div class="workspace"><header class="topbar"><div style="display:flex;align-items:center;gap:13px"><button class="icon-button mobile-menu" data-action="mobile" aria-label="Abrir menú">${icon('menu',19)}</button><div class="breadcrumb"><span>ME&I Workspace</span>${icon('right',11)}<strong>${title}</strong></div></div><div class="top-actions"><span class="private-tag">${icon('help',12)}<span>Acceso público</span></span><span class="top-divider"></span><button class="icon-button" data-action="method" aria-label="Abrir guía" title="Guía de interpretación">${icon('help',17)}</button><button class="icon-button" data-action="settings" aria-label="Configurar fecha de corte y OH" title="Configuración">${icon('settings',17)}</button><span class="avatar" title="ME&I">ME</span></div></header><main class="main ${state.view==='overview'?'main-overview':state.view==='oh'?'main-oh':state.view==='projects'?'main-projects':state.view==='team'?'main-team':''}" id="main" tabindex="-1"><div class="page-heading"><div><p class="eyebrow">RESOURCE & PROJECT INTELLIGENCE</p><h1 class="page-title">${title}<span class="fy-tag">${esc([...new Set(state.dataset.records.map(r=>r.fy))].join(' · '))}</span></h1><p class="page-subtitle">${subtitle}</p></div><div class="heading-actions"><button class="button" data-action="nav" data-value="data">${icon('upload',13)}Actualizar Excel</button><div class="export-wrap"><button class="button primary" data-action="export-menu" aria-expanded="${state.exportOpen}">${icon('download',13)}Exportar${icon('chevron',12)}</button>${state.exportOpen?`<div class="export-menu"><button data-action="export-detail">${icon('file',14)}Detalle del contexto · CSV</button><button data-action="export-summary">${icon('overview',14)}Indicadores · CSV</button><button data-action="print">${icon('print',14)}Imprimir vista</button></div>`:''}</div></div></div>${state.view==='data'?'':filtersPanel()}${state.view==='data'?'':`<div class="notice">${icon('info',13)}<span><strong>Análisis histórico.</strong> Horas ya registradas en el sistema, según el Excel. Los porcentajes describen la distribución del tiempo registrado.</span></div>`}${m.future&&state.view!=='data'?`<div class="notice warning">${icon('warning',14)}<span>El contexto incluye <strong>${hrs(m.future)}</strong> posteriores al corte ${dateLabel(state.settings.cutoff)}. Revisa las fechas de estos registros en la fuente. No se interpretan como planificación.</span>${state.view==='capacity'?'<button data-action="nav" data-value="quality">Revisar fechas</button>':'<button data-action="apply-cutoff">Aplicar corte</button>'}</div>`:''}<div id="view-content">${pageContent()}</div><footer class="page-footer"><span>ME&I Resource & OH Intelligence · ${esc(pageContext())}</span><span>Fuente: Excel de seguimiento · Corte: ${dateLabel(state.settings.cutoff,{day:'numeric',month:'short',year:'numeric'})} · <button data-action="method">Método y definiciones</button></span></footer></main></div>`;
  if(focus){const input=document.querySelector(focus);if(input){input.focus({preventScroll:true});if(selection!==null&&input.setSelectionRange)try{input.setSelectionRange(selection,selection)}catch{}}}
}

function pageContent(){return ({overview:overviewPage,capacity:capacityPage,projects:projectsPage,oh:ohPage,team:teamPage,work:workPage,quality:qualityPage,data:dataPage}[state.view])()+(state.view==='quality'?qualitySupplement():'');}
function historyKpis(m){return kpiGrid([
 kpi('Horas registradas',num(m.total,1),{unit:'h',note:'Proyecto + OH + ausencias + sin clasificar',accent:true}),
 kpi('Horas de proyecto',num(m.project,1),{unit:'h',glyph:'projects',note:`${pct(ratio(m.project,m.total))} del total registrado`}),
 kpi('Horas de Overhead',num(m.oh,1),{unit:'h',glyph:'oh',tone:'pink',note:`${pct(m.ohMix)} de Proyecto + OH`}),
 kpi('Personas con registros',num(m.activePeople),{glyph:'users',note:`${m.projects.length} proyectos con horas`})]);}
function historicalDisciplines(m){return hbars(groupFacts(m.facts,'discipline').map(g=>({key:g.key,label:g.key,value:g.hours})),{key:'discipline',limit:20});}
function overviewPage(){const m=state.model;
 const parts=[{label:'Proyecto',type:'Proyecto',value:m.project,color:COLORS.project},{label:'Overhead',type:'Overhead',value:m.oh,color:COLORS.oh},{label:'Ausencias',type:'Ausencia',value:m.absence,color:COLORS.absence},{label:'Sin clasificar',type:'Sin clasificar',value:m.unknown,color:COLORS.unknown}];
 const positive=sum(parts,p=>Math.max(0,p.value)),top3=sum(m.projects.slice(0,3),p=>p.hours);
 const ohGroups=groupFacts(m.facts.filter(r=>r.type==='Overhead'),'ohGroup');
 const disciplines=groupFacts(m.facts,'discipline');
 const heading=(n,label,title,action)=>`<div class="ov-section-head"><div><span class="ov-kicker">${n} / ${label}</span><h2>${title}</h2></div>${action||''}</div>`;
 return `<div class="ov-editorial">
 <section class="ov-hero" aria-label="Resumen del período"><div class="ov-hero-main"><span class="ov-kicker">EL TIEMPO REGISTRADO, EN PERSPECTIVA</span><div class="ov-total">${num(m.total,1)}<span>h</span></div><p>Horas que cuentan la historia<br>del equipo.</p><div class="ov-date">${icon('calendar',13)}${esc(pageContext())}</div></div>
 <div class="ov-hero-detail"><div class="ov-hero-top"><span>Distribución del período</span><span class="ov-live-label">HISTÓRICO</span></div><div class="ov-composition" aria-label="Distribución de horas por tipo">${parts.filter(p=>p.value>0).map(p=>`<button style="flex:${p.value/positive};background:${p.color}" ${filterAttrs('type',p.type)} title="${p.label}: ${hrs(p.value)} · ${pct(ratio(p.value,m.total))}" aria-label="Filtrar ${p.label}: ${hrs(p.value)}"></button>`).join('')||'<span class="ov-no-composition">Sin horas positivas para representar</span>'}</div><div class="ov-type-grid">${parts.map(p=>`<button class="ov-type" ${filterAttrs('type',p.type)}><span class="ov-type-name"><i style="background:${p.color}"></i>${p.label}</span><strong>${num(p.value,1)}<small> h</small></strong><span>${pct(ratio(p.value,m.total))} del total ${icon('right',12)}</span></button>`).join('')}</div>${parts.some(p=>p.value<0)?'<p class="ov-negative-note">La barra representa valores positivos; las cifras conservan los ajustes negativos.</p>':''}<div class="ov-hero-bottom"><button data-action="nav" data-value="team"><strong>${num(m.activePeople)}</strong> personas con registros ${icon('right',12)}</button><button data-action="nav" data-value="projects"><strong>${num(m.projects.length)}</strong> proyectos con horas ${icon('right',12)}</button></div></div></section>
 <div class="ov-main-grid"><section class="ov-panel ov-evolution">${heading('01','RITMO DEL PERÍODO','Cómo se distribuyeron las horas',grainControl())}<div class="ov-chart-meta"><span><strong>${hrs(m.booked,1)}</strong> en Proyecto + OH</span><button class="text-link" data-action="nav" data-value="capacity">Comparar meses ${icon('right',12)}</button></div>${trendChart(trend(m,state.grain),{grain:state.grain,series:state.series})}<p class="ov-chart-note">Selecciona una barra para filtrar el período. Activa o desactiva las series en la leyenda.</p></section>
 <section class="ov-oh">${heading('02','FOCO OVERHEAD','El contexto detrás del OH')}<div class="ov-oh-number">${pct(m.ohMix)}<span>de Proyecto + OH</span></div><p class="ov-oh-description">${hrs(m.oh,1)} registradas fuera de proyectos. Su categoría explica en qué se emplearon.</p><div class="ov-oh-list">${ohGroups.slice(0,3).map((g,i)=>`<button ${filterAttrs('ohGroup',g.key)}><span><i style="background:${OH_COLORS[Math.max(0,OH_GROUPS.indexOf(g.key))]}"></i>${esc(g.key)}</span><strong>${pct(ratio(g.hours,m.oh))}</strong></button>`).join('')||'<p>Sin registros de OH en este contexto.</p>'}</div><button class="ov-oh-link" data-action="nav" data-value="oh">Explorar Overhead ${icon('arrow',18)}</button></section></div>
 <div class="ov-bottom-grid"><section class="ov-panel ov-projects">${heading('03','DEDICACIÓN A PROYECTOS','Dónde se concentró el esfuerzo',`<button class="text-link" data-action="nav" data-value="projects">Ver todos ${icon('right',12)}</button>`)}<div class="ov-project-caption"><span>Proyecto / código</span><span>Horas · participación</span></div>${m.projects.slice(0,5).map((p,i)=>`<button class="ov-project-row" data-action="project-detail" data-value="${esc(p.key)}"><span class="ov-rank">${String(i+1).padStart(2,'0')}</span><span class="ov-project-info"><strong>${esc(p.name)}</strong><small>${esc(p.code||'Sin código')} · ${p.people} personas</small><span class="ov-project-track"><i style="width:${Math.max(0,Math.min(100,(p.share||0)*100))}%"></i></span></span><span class="ov-project-value"><strong>${hrs(p.hours,1)}</strong><small>${pct(p.share)} de proyecto</small></span>${icon('right',14)}</button>`).join('')||emptyChart()}<div class="ov-project-foot"><strong>${pct(ratio(top3,m.project))}</strong><span>de las horas de proyecto se concentran en los ${Math.min(3,m.projects.length)} primeros.</span></div></section>
 <section class="ov-panel ov-disciplines">${heading('04','LECTURA DEL EQUIPO','Participación por disciplina')}<p class="ov-chart-note">Todas las horas registradas del contexto.</p><div class="ov-discipline-list">${disciplines.map((d,i)=>`<button class="ov-discipline-row" ${filterAttrs('discipline',d.key)}><span class="ov-discipline-index">${String(i+1).padStart(2,'0')}</span><span class="ov-discipline-info"><span><strong>${esc(d.key)}</strong><small>${pct(ratio(d.hours,m.total))}</small></span><span class="ov-discipline-track"><i style="width:${Math.max(0,Math.min(100,ratio(d.hours,Math.max(...disciplines.map(x=>x.hours),1))*100))}%"></i></span></span><b>${hrs(d.hours,0)}</b></button>`).join('')||emptyChart()}</div></section></div>
 <section class="ov-review" aria-label="Trazabilidad y calidad"><span class="ov-review-icon">${icon('quality',23)}</span><div><span class="ov-kicker">ANTES DE SACAR CONCLUSIONES</span><p>${m.unknown||m.unclassifiedOH?`<strong>${hrs(m.unknown,1)}</strong> sin tipo de hora y <strong>${hrs(m.unclassifiedOH,1)}</strong> de OH sin categoría asignada.`:'Los tipos de hora y la categoría OH están clasificados en este contexto.'}<small>${num(m.facts.length)} registros diarios con acceso a su hoja y celda de origen.</small></p></div><button data-action="nav" data-value="quality">Revisar trazabilidad ${icon('arrow',17)}</button></section>
 </div>`;
}

function table(id,rows,columns,{defaultSort='',descending=true,search=true,pageSize=12,empty='No hay registros con estos filtros.'}={}){
  const t=state.tables[id]||(state.tables[id]={page:1,query:'',sort:defaultSort,direction:descending?-1:1});
  let filtered=rows.filter(r=>!t.query||norm(columns.map(c=>c.search?c.search(r):c.value?c.value(r):'').join(' ')).includes(norm(t.query)));
  const sort=columns.find(c=>c.key===t.sort);if(sort?.value)filtered=[...filtered].sort((a,b)=>{const va=sort.value(a),vb=sort.value(b);return t.direction*(typeof va==='number'&&typeof vb==='number'?va-vb:String(va??'').localeCompare(String(vb??''),'es'));});
  const total=filtered.length,pages=Math.max(1,Math.ceil(total/pageSize));t.page=Math.min(t.page,pages);const shown=filtered.slice((t.page-1)*pageSize,t.page*pageSize);
  return `${search?`<div class="table-toolbar"><span>${num(total)} ${id==='resources'?'colaboradores':id==='projects'?'proyectos':'registros'}</span><input class="table-search" type="search" data-table-search="${id}" placeholder="Buscar en esta tabla…" value="${esc(t.query)}" aria-label="Buscar en tabla"></div>`:''}<div class="table-scroll"><table class="data-table"><thead><tr>${columns.map(c=>`<th class="${c.numeric?'numeric':''}" ${c.key?`aria-sort="${t.sort===c.key?(t.direction===1?'ascending':'descending'):'none'}"`:''}>${c.key?`<button data-action="table-sort" data-table="${id}" data-key="${c.key}">${esc(c.label)}${t.sort===c.key?`<span style="font-size:9px">${t.direction===1?'↑':'↓'}</span>`:icon('sort',10)}</button>`:esc(c.label)}</th>`).join('')}</tr></thead><tbody>${shown.length?shown.map(r=>`<tr>${columns.map(c=>`<td class="${c.numeric?'numeric ':''}${c.className||''}">${c.cell?c.cell(r):esc(c.value(r))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}"><div class="empty-state compact"><p>${esc(empty)}</p></div></td></tr>`}</tbody></table></div><div class="table-pagination"><span>${total?`${(t.page-1)*pageSize+1}–${Math.min(t.page*pageSize,total)} de ${num(total)}`:'0 registros'}${t.query?' · búsqueda de tabla':''}</span><div class="pagination-buttons"><button data-action="table-page" data-table="${id}" data-value="${t.page-1}" ${t.page===1?'disabled':''} aria-label="Página anterior">Anterior</button><span>${t.page} / ${pages}</span><button data-action="table-page" data-table="${id}" data-value="${t.page+1}" ${t.page===pages?'disabled':''} aria-label="Página siguiente">Siguiente</button></div></div>`;
}
function recordsTable(facts=state.model.facts,id='facts'){
  return table(id,facts,[
    {key:'date',label:'Fecha',value:r=>r.date,cell:r=>dateLabel(r.date,{day:'2-digit',month:'short',year:'2-digit'})},
    {key:'name',label:'Colaborador',value:r=>r.name,cell:r=>`<span class="cell-name"><button data-action="person" data-value="${esc(r.person)}">${esc(r.name)}</button></span><small class="cell-secondary">${esc(r.discipline)} · ${esc(r.role)}</small>`},
    {key:'project',label:'Proyecto / concepto',value:r=>r.project,cell:r=>`<div class="cell-truncate" title="${esc(r.project)}">${esc(r.project)}</div><small class="cell-secondary">${esc(r.code||'Sin código')}</small>`},
    {key:'type',label:'Tipo',value:r=>r.type,cell:r=>`<span class="tag ${r.type==='Proyecto'?'green':r.type==='Overhead'?'pink':r.type==='Sin clasificar'?'yellow':''}">${esc(r.type)}</span>`},
    {key:'task',label:'Task / categoría',value:r=>r.task,cell:r=>`<div class="cell-truncate" title="${esc(r.task+' · '+r.category)}">${esc(r.task||'Sin Task')}</div><small class="cell-secondary">${esc(r.category)}</small>`},
    {key:'hours',label:'Horas',numeric:true,value:r=>r.hours,cell:r=>num(r.hours,2)},
    {label:'Origen',value:r=>r.source+' '+r.cell,cell:r=>`<button class="button small" data-action="record" data-id="${r.id}" title="Ver registro ${esc(r.source+'!'+r.cell)}">${icon('eye',12)}${esc(r.cell)}</button>`}
  ],{defaultSort:'date'});
}

function monthlyComparison(){
 const filters={...state.filters,months:[],weeks:[],from:'',to:'',status:[]};
 const model=analyze(state.dataset,filters,state.settings);
 const months=[...new Set(state.dataset.records.map(r=>r.month))].sort();
 return months.map((month,i)=>{const facts=model.facts.filter(r=>r.month===month),dates=[...new Set(facts.map(r=>r.date))].sort(),total=sum(facts,r=>r.hours),project=sum(facts.filter(r=>r.type==='Proyecto'),r=>r.hours),oh=sum(facts.filter(r=>r.type==='Overhead'),r=>r.hours);const prev=i?model.facts.filter(r=>r.month===months[i-1]):null,previous=prev?sum(prev,r=>r.hours):null;return {month,total,project,oh,days:dates.length,first:dates[0],last:dates.at(-1),people:new Set(facts.map(r=>r.person)).size,delta:previous===null?null:total-previous,change:previous===null||previous<=0?null:(total-previous)/previous,mix:ratio(oh,project+oh)};});
}
function capacityPage(){const rows=monthlyComparison();
 const columns=[{key:'month',label:'Mes',value:r=>r.month,cell:r=>`<button class="text-link" ${filterAttrs('months',r.month)}>${monthLabel(r.month)}</button>`},
 {key:'total',label:'Horas registradas',numeric:true,value:r=>r.total,cell:r=>num(r.total,1)},
 {key:'project',label:'Proyecto (h)',numeric:true,value:r=>r.project,cell:r=>num(r.project,1)},
 {key:'oh',label:'OH (h)',numeric:true,value:r=>r.oh,cell:r=>num(r.oh,1)},
 {key:'mix',label:'OH / (Proyecto + OH)',numeric:true,value:r=>r.mix,cell:r=>pct(r.mix)},
 {key:'delta',label:'Variación (h)',numeric:true,value:r=>r.delta,cell:r=>num(r.delta,1)},
 {key:'change',label:'Variación (%)',numeric:true,value:r=>r.change,cell:r=>pct(r.change)},
 {key:'people',label:'Personas con horas',numeric:true,value:r=>r.people},
 {key:'days',label:'Días con registros',numeric:true,value:r=>r.days},
 {key:'range',label:'Primera / última fecha',value:r=>r.first||'',cell:r=>r.first?`${dateLabel(r.first)} / ${dateLabel(r.last)}`:'Sin registros'}];
 return `<div class="callout"><strong>Comparación de todo el histórico.</strong> Esta vista conserva los filtros de persona, disciplina, proyecto, tipo, Task y calidad. Ignora mes, semana, desde, hasta y corte para mostrar todos los meses del archivo. Las variaciones comparan con el mes anterior disponible y no están normalizadas por días laborables. Un mes con registros no implica un cierre completo.</div><div class="grid equal">${card('Horas por mes','Selecciona un mes en la gráfica para aplicarlo al resto de las vistas',hbars(rows.map(r=>({key:r.month,label:monthLabel(r.month),value:r.total})),{key:'months',limit:100}))}${card('Participación mensual del OH','OH / (Proyecto + OH), sin ausencias ni horas sin clasificar',hbars(rows.filter(r=>r.mix!==null).map(r=>({key:r.month,label:monthLabel(r.month),value:r.mix})),{key:'months',limit:100,valueFormat:pct,color:COLORS.oh}))}</div>${card('Comparación mensual','Valores absolutos y cambios frente al período anterior disponible',table('monthly-comparison',rows,columns,{defaultSort:'month',descending:false,search:false,pageSize:24}))}<p class="section-note">Días con registros cuenta fechas distintas con horas, incluidos fines de semana y ausencias. No mide días laborables ni completitud del cargue. Las fechas posteriores al corte configurado deben revisarse en Calidad de datos.</p>`;
}

function projectsPage(){const m=state.model,projectPeople=new Set(m.facts.filter(r=>r.type==='Proyecto').map(r=>r.person)),top3=sum(m.projects.slice(0,3),p=>p.hours);
 const shown=m.projects.filter(p=>!state.projectQuery||norm(p.name+' '+p.code).includes(norm(state.projectQuery)));
 const selected=shown.find(p=>p.key===state.projectFocus)||shown[0];
 const summary=`<div class="pr-summary"><div><span>PORTAFOLIO DEL PERÍODO</span><strong>${m.projects.length}<small> proyectos con horas</small></strong></div><div><span>DEDICACIÓN REGISTRADA</span><strong>${hrs(m.project,1)}</strong></div><div><span>PARTICIPACIÓN DEL EQUIPO</span><strong>${projectPeople.size}<small> personas</small></strong></div><div><span>CONCENTRACIÓN TOP 3</span><strong>${pct(ratio(top3,m.project))}</strong></div></div>`;
 const picker=`<aside class="pr-picker"><div class="pr-picker-title"><h2>Explorar proyectos</h2><span>${shown.length}</span></div><label class="pr-search">${icon('search',15)}<input id="project-search" type="search" value="${esc(state.projectQuery||'')}" placeholder="Nombre o código…" aria-label="Buscar proyecto por nombre o código"></label><p>Ordenados por horas registradas</p><div class="pr-project-list">${shown.map((p,i)=>`<button data-action="project-select" data-value="${esc(p.key)}" class="${selected?.key===p.key?'selected':''}" aria-pressed="${selected?.key===p.key}"><span class="pr-project-number">${String(i+1).padStart(2,'0')}</span><span class="pr-project-name"><strong>${esc(p.name)}</strong><small>${esc(p.code||'Sin código')}</small></span><span class="pr-project-hours">${num(p.hours,1)}<small>h</small></span></button>`).join('')||'<div class="pr-empty">No hay proyectos que coincidan. Prueba otro nombre o ajusta los filtros.</div>'}</div></aside>`;
 let detail=emptyChart('Selecciona otros filtros o borra la búsqueda para explorar proyectos.');
 if(selected){const p=selected,discs=groupFacts(p.records,'discipline'),people=groupFacts(p.records,'person'),categories=groupFacts(p.records,'category'),dates=[...new Set(p.records.map(r=>r.date))].sort();
 const timeline=trend({...m,facts:p.records},state.grain);
 const staff=table('project-team',people,[{key:'name',label:'Colaborador',value:g=>g.records[0].name,cell:g=>`<button class="text-link" data-action="project-person" data-project="${esc(p.key)}" data-value="${esc(g.key)}">${esc(g.records[0].name)}</button><small class="cell-secondary">${esc([...new Set(g.records.map(r=>r.discipline))].join(' · '))}</small>`},{key:'hours',label:'Horas',numeric:true,value:g=>g.hours,cell:g=>num(g.hours,1)},{key:'share',label:'% del proyecto',numeric:true,value:g=>ratio(g.hours,p.hours)??-1,cell:g=>pct(ratio(g.hours,p.hours))},{key:'days',label:'Días con registros',numeric:true,value:g=>new Set(g.records.map(r=>r.date)).size}],{defaultSort:'hours',pageSize:8});
 detail=`<div class="pr-project-sheet"><div class="pr-sheet-heading"><div><span class="pr-code">${icon('projects',14)}${esc(p.code||'Sin código de proyecto')}</span><h2>${esc(p.name)}</h2><p>Fechas con registros: ${dates.length?dateLabel(dates[0])+' a '+dateLabel(dates.at(-1)): 's/d'} · ${esc(pageContext())}</p></div><button class="button small" data-action="project-detail" data-value="${esc(p.key)}">${icon('file',13)}Ver registros</button></div><div class="pr-project-stats"><div><strong>${hrs(p.hours,1)}</strong><span>Horas del proyecto</span></div><div><strong>${pct(p.share)}</strong><span>Del total de proyecto</span></div><div><strong>${p.people}</strong><span>Personas participantes</span></div><div><strong>${discs.length}</strong><span>Disciplinas</span></div></div><section class="pr-timeline"><div class="pt-panel-heading"><div><h3>Dedicación en el tiempo</h3><p>Horas registradas en este proyecto</p></div>${grainControl()}</div>${trendChart(timeline,{grain:state.grain,series:['project']}).replace(/<div class="legend">[\s\S]*$/,'')}<div class="pr-timeline-note"><i></i>Proyecto · selecciona un período para filtrar</div></section><div class="pr-breakdowns"><section><h3>Aporte por disciplina</h3>${hbars(discs.map(g=>({key:g.key,label:g.key,value:g.hours})),{key:'discipline',limit:30,color:'#537cba'})}</section><section><h3>Actividades del proyecto</h3>${hbars(categories.map(g=>({key:g.key,label:g.key,value:g.hours})),{key:'category',limit:5,color:'#6a9eae'})}</section></div><section class="pr-team"><div class="pt-panel-heading"><div><h3>El equipo detrás de las horas</h3><p>Abre una persona para ver su participación en este proyecto.</p></div><span class="pr-count">${people.length} personas</span></div>${staff}</section></div>`;
 }
 return `<div class="pr-page">${summary}<div class="pr-layout">${picker}<div class="pr-detail">${detail}</div></div><p class="pt-footnote">La selección del explorador muestra el detalle de un proyecto. Los filtros superiores y la exportación mantienen el contexto del portafolio. Las horas describen dedicación histórica; no representan avance, presupuesto ni rentabilidad.</p></div>`;
}

function ohTimeline(periods,grain){
 if(!periods.length)return emptyChart('No hay períodos con estos filtros.');
 const W=Math.max(680,periods.length*29+65),H=280,L=48,R=12,T=20,B=42,ph=H-T-B,pw=W-L-R;
 const totals=periods.map(p=>({positive:sum(OH_GROUPS,g=>Math.max(0,p[g]||0)),negative:sum(OH_GROUPS,g=>Math.min(0,p[g]||0))}));
 const high=Math.max(1,...totals.map(t=>t.positive))*1.1,low=Math.min(0,...totals.map(t=>t.negative))*1.1,span=high-low;
 const y=v=>T+(high-v)/span*ph,x=i=>L+(i+.5)*pw/periods.length,bw=Math.min(34,pw/periods.length*.64);
 const ticks=Array.from({length:5},(_,i)=>low+span*i/4);
 const grid=ticks.map(v=>`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e9ebef"/><text x="${L-9}" y="${y(v)+3}" text-anchor="end" fill="#76818f" font-size="10">${short(v)}</text>`).join('');
 const bars=periods.map((p,i)=>{let plus=0,minus=0;const parts=OH_GROUPS.map((g,j)=>{const v=p[g]||0;if(!v)return '';const base=v>0?plus:minus;if(v>0)plus+=v;else minus+=v;const top=y(Math.max(base,base+v)),h=Math.abs(v)/span*ph;return `<rect x="${x(i)-bw/2}" y="${top}" width="${bw}" height="${h}" fill="${OH_COLORS[j]}"/>`;}).join('');const label=grain==='month'?dateLabel(p.key+'-01',{month:'short',year:'2-digit'}):dateLabel(p.key);return `<g class="chart-point" tabindex="0" role="button" ${filterAttrs(grain==='month'?'months':grain==='day'?'date':'weeks',p.key)} aria-label="Filtrar ${esc(p.label)}: ${hrs(sum(OH_GROUPS,g=>p[g]))}"><title>${esc(p.label)}${OH_GROUPS.map(g=>'\n'+g+': '+hrs(p[g])).join('')}</title><rect x="${x(i)-bw/2-3}" y="${T}" width="${bw+6}" height="${ph}" fill="transparent"/>${parts}</g>${periods.length<22||i%Math.ceil(periods.length/18)===0?`<text x="${x(i)}" y="${H-17}" text-anchor="middle" font-size="10" fill="#76818f">${esc(label)}</text>`:''}`;}).join('');
 return `<div class="oh-chart-scroll"><svg viewBox="0 0 ${W} ${H}" style="min-width:${W}px" role="img" aria-label="Horas históricas de OH por categoría y período"><text x="${L}" y="11" fill="#7c8794" font-size="9">h</text>${grid}<line x1="${L}" x2="${W-R}" y1="${y(0)}" y2="${y(0)}" stroke="#bac3ce"/>${bars}</svg></div><div class="oh-chart-legend">${OH_GROUPS.map((g,i)=>`<button ${filterAttrs('ohGroup',g)} title="Filtrar ${esc(g)}"><i style="background:${OH_COLORS[i]}"></i>${esc(g)}</button>`).join('')}</div>`;
}
function ohPage(){const m=state.model,ohFacts=m.facts.filter(r=>r.type==='Overhead');
 const byTask=groupFacts(ohFacts,r=>r.task||'Sin Task').map(g=>({...g,taskName:OH_TASK_CATALOG[taskKey(g.key)]?.name||'Task fuera del catálogo',group:[...new Set(g.records.map(r=>r.ohGroup))].join(' / '),concepts:[...new Set(g.records.map(r=>r.project))].join(' · '),people:new Set(g.records.map(r=>r.person)).size}));
 const taxonomy=OH_GROUPS.map((name,i)=>({name,hours:sum(ohFacts.filter(r=>r.ohGroup===name),r=>r.hours),color:OH_COLORS[i]}));
 const descriptions=['1.01 · Gastos generales y gestión del equipo','2.01 · Evaluación y preparación de propuestas','3.01–3.06 · Formación técnica, de proyecto, digital, no técnica, calidad e IA','4.01–4.03 · Graduates, Colombia Hypercare y SH&E','5.01–5.02 · Sin proyecto o problemas de IT','Control de calidad: Task fuera del catálogo aportado'];
 const periodKey=r=>state.grain==='month'?r.month:state.grain==='day'?r.date:r.week;
 const keys=[...new Set(m.dates.map(date=>periodKey({date,month:date.slice(0,7),week:weekKey(date)})))].sort();
 const periods=keys.map(key=>{const g={key,label:state.grain==='month'?monthLabel(key):dateLabel(key)};OH_GROUPS.forEach(n=>g[n]=sum(ohFacts.filter(r=>periodKey(r)===key&&r.ohGroup===n),r=>r.hours));return g;});
 const cols=[...new Set(ohFacts.map(r=>r.discipline))].sort(),top3=sum(byTask.slice(0,3),t=>t.hours),people=new Set(ohFacts.map(r=>r.person)).size;
 const dominant=[...taxonomy].sort((a,b)=>b.hours-a.hours)[0];
 const matrixRows=byTask.slice(0,10),maxCell=Math.max(1,...matrixRows.flatMap(t=>cols.map(d=>sum(t.records.filter(r=>r.discipline===d),r=>r.hours))));
 const taskTable=table('oh-tasks',byTask,[
 {key:'task',label:'Task',value:r=>r.key,cell:r=>`<button class="text-link" data-action="oh-detail" data-value="${esc(r.key==='Sin Task'?'':r.key)}">${esc(r.key)}</button><small class="cell-secondary">${esc(r.taskName)}</small>`},
 {key:'concepts',label:'Conceptos registrados',value:r=>r.concepts,cell:r=>`<span class="cell-truncate" style="display:block;max-width:340px" title="${esc(r.concepts)}">${esc(r.concepts)}</span>`},
 {key:'group',label:'Categoría OH',value:r=>r.group},
 {key:'hours',label:'Horas',numeric:true,value:r=>r.hours,cell:r=>num(r.hours,1)},
 {key:'share',label:'% del OH',numeric:true,value:r=>ratio(r.hours,m.oh)??-1,cell:r=>pct(ratio(r.hours,m.oh))},
 {key:'people',label:'Personas',numeric:true,value:r=>r.people},
 {label:'Registros',value:r=>r.key,cell:r=>`<button class="button small" data-action="oh-detail" data-value="${esc(r.key==='Sin Task'?'':r.key)}">Ver detalle ${icon('right',12)}</button>`}
 ],{defaultSort:'hours'});
 return `<div class="oh-studio"><div class="oh-studio-label"><span>${icon('grid',15)} EXPLORADOR DE OVERHEAD</span><span>${esc(pageContext())}</span></div><div class="oh-workbench"><aside class="oh-category-rail"><div class="oh-rail-heading"><h2>Categorías</h2><button class="icon-button" data-action="settings-oh" title="Abrir catálogo oficial" aria-label="Abrir catálogo oficial">${icon('info',16)}</button></div><button class="oh-rail-all ${state.filters.ohGroup.length?'':'active'}" data-action="clear-filter" data-key="ohGroup"><span>Todas las categorías</span>${icon('grid',13)}</button><div class="oh-category-options">${taxonomy.map((g,i)=>`<button class="oh-category-option ${state.filters.ohGroup.includes(g.name)?'active':''}" style="--category-color:${g.color}" ${filterAttrs('ohGroup',g.name)} aria-pressed="${state.filters.ohGroup.includes(g.name)}"><span class="oh-category-title"><i></i>${esc(g.name)}${icon('right',12)}</span><span class="oh-category-amount">${hrs(g.hours,1)}<small>${pct(ratio(g.hours,m.oh))}</small></span><span class="oh-category-desc">${descriptions[i]}</span></button>`).join('')}</div><div class="oh-rail-note">Cinco categorías oficiales.<br>«Sin clasificar» identifica Tasks pendientes de revisión.</div><button class="oh-catalog-link" data-action="settings-oh">Consultar catálogo de Tasks ${icon('external',13)}</button></aside>
 <div class="oh-workspace"><section class="oh-metric-strip" aria-label="Indicadores de Overhead"><div class="oh-primary-metric"><span>Horas de Overhead</span><strong>${num(m.oh,1)}<small> h</small></strong><span>${num(ohFacts.length)} registros diarios</span></div><div><span>Participación de OH</span><strong>${pct(m.ohMix)}</strong><span>OH / (Proyecto + OH)</span></div><div><span>Personas con OH</span><strong>${num(people)}</strong><span>${byTask.length} Tasks · ${cols.length} disciplinas</span></div></section>
 <section class="oh-analysis-surface"><div class="oh-analysis-toolbar"><div class="oh-view-tabs" role="group" aria-label="Vista del análisis"><button data-action="oh-panel" data-value="timeline" class="${state.ohPanel!=='matrix'?'active':''}" aria-pressed="${state.ohPanel!=='matrix'}">${icon('trend',15)}Evolución temporal</button><button data-action="oh-panel" data-value="matrix" class="${state.ohPanel==='matrix'?'active':''}" aria-pressed="${state.ohPanel==='matrix'}">${icon('grid',15)}Task × disciplina</button></div>${state.ohPanel==='matrix'?'<span class="oh-panel-tag">TOP 10 TASKS</span>':grainControl()}</div>
 <div class="oh-analysis-heading"><div><h2>${state.ohPanel==='matrix'?'Cruza las horas con el equipo':'El OH a lo largo del período'}</h2><p>${state.ohPanel==='matrix'?'Abre cualquier celda para consultar los registros que la componen.':'Barras por período, segmentos por categoría. Selecciona una barra para filtrar sus fechas.'}</p></div><span class="oh-unit">HORAS REGISTRADAS</span></div>
 ${state.ohPanel==='matrix'?`<div class="oh-studio-matrix">${matrixRows.length&&cols.length?`<div class="heatmap-wrap"><table class="heatmap"><thead><tr><th>Task</th>${cols.map(d=>`<th><button ${filterAttrs('discipline',d)}>${esc(d)}</button></th>`).join('')}</tr></thead><tbody>${matrixRows.map(t=>`<tr><td><button data-action="oh-detail" data-value="${esc(t.key==='Sin Task'?'':t.key)}">${esc(t.key)}</button></td>${cols.map(d=>{const h=sum(t.records.filter(r=>r.discipline===d),r=>r.hours),alpha=.05+.7*Math.max(0,h)/maxCell;return `<td><button data-action="oh-detail" data-value="${esc(t.key==='Sin Task'?'':t.key)}" data-discipline="${esc(d)}" style="background:rgba(160,42,105,${alpha});color:${h/maxCell>.6?'#fff':'#65384f'}" title="Task ${esc(t.key)} · ${esc(d)}: ${hrs(h,2)}" aria-label="Ver registros de Task ${esc(t.key)}, ${esc(d)}: ${hrs(h,2)}">${num(h,1)}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="oh-scale"><span>Menos horas</span><i></i><span>Más horas</span></div>`:emptyChart()}</div>`:`<div class="oh-period-chart">${ohTimeline(periods,state.grain)}</div>`}
 <div class="oh-analysis-foot"><span>${icon('filter',12)}Los filtros activos se aplican a todos los resultados.</span><button data-action="method">Cómo leer este análisis ${icon('right',12)}</button></div></section>
 <section class="oh-findings" aria-label="Lectura del contexto"><div><span>Mayor categoría</span><strong>${m.oh>0?esc(dominant.name):'Sin base positiva'}</strong><small>${m.oh>0?pct(ratio(dominant.hours,m.oh))+' del OH':'Revisa el contexto'}</small></div><div><span>Concentración Top 3 Tasks</span><strong>${pct(ratio(top3,m.oh))}</strong><small>Participación sobre las horas de OH</small></div><div><span>Non-productive</span><strong>${hrs(m.lost,1)}</strong><small>Sin proyecto y problemas de IT</small></div></section>
 <section class="oh-task-ledger"><div class="oh-ledger-heading"><div><span>DETALLE DEL REGISTRO</span><h2>Tasks y conceptos</h2></div><span class="oh-ledger-count">${byTask.length} Tasks</span></div><p class="oh-ledger-note">Ordena las columnas o abre una Task para consultar personas, comentarios y celdas de origen.</p>${taskTable}</section>
 <div class="oh-studio-footer"><span>${icon('quality',16)}<strong>${hrs(m.unclassifiedOH,1)}</strong> de OH sin categoría asignada.</span><button data-action="settings-oh">Revisar clasificación ${icon('arrow',15)}</button></div><p class="oh-scope-note">Los porcentajes usan el contexto filtrado. Seleccionar solo OH puede llevar su participación al 100%. Las horas describen registros históricos, no disponibilidad actual.</p>
 </div></div></div>`;
}
function openOHDetail(task,discipline=null){
 const facts=state.model.facts.filter(r=>r.type==='Overhead'&&r.task===task&&(discipline===null||r.discipline===discipline));
 showModal(`OH · Task ${esc(task||'sin Task')}`,`${discipline===null?'Todas las disciplinas del contexto':esc(discipline)} · ${hrs(sum(facts,r=>r.hours),2)}`,recordsTable(facts,'oh-detail-facts'),`<span>${facts.length} registros · ${new Set(facts.map(r=>r.person)).size} personas. Cada fila permite consultar su celda de origen.</span><button class="button primary" data-action="close-modal">Cerrar</button>`,true);
 state.modal='oh-detail';state.ohDetail={task,discipline};
}

function personMix(p){const values=[p.project,p.oh,p.total-p.project-p.oh-p.unknown,p.unknown],colors=[COLORS.project,COLORS.oh,COLORS.absence,COLORS.unknown],labels=['Proyecto','OH','Ausencias','Sin clasificar'],positive=sum(values,v=>Math.max(0,v));return `<div class="tm-mix" aria-label="Distribución de horas de ${esc(p.name)}">${values.map((v,i)=>v>0?`<span style="width:${v/positive*100}%;background:${colors[i]}" title="${labels[i]}: ${hrs(v,1)}"></span>`:'').join('')}</div>`;}
function teamPage(){const m=state.model,one=state.filters.person.length===1?m.people.find(p=>p.person===state.filters.person[0]):null;
 if(!one){const roster=table('team-directory',m.people,[
 {key:'name',label:'Colaborador',value:p=>p.name,cell:p=>`<button class="tm-name" data-action="person" data-value="${esc(p.person)}"><span class="tm-avatar">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></span></button>`},
 {key:'discipline',label:'Disciplina',value:p=>p.discipline,cell:p=>`<button class="tm-discipline" ${filterAttrs('discipline',p.discipline)}>${esc(p.discipline)}</button>`},
 {key:'total',label:'Total h',numeric:true,value:p=>p.total,cell:p=>num(p.total,1)},
 {key:'project',label:'Proyecto h',numeric:true,value:p=>p.project,cell:p=>num(p.project,1)},
 {key:'oh',label:'OH h',numeric:true,value:p=>p.oh,cell:p=>num(p.oh,1)},
 {key:'projects',label:'Proyectos',numeric:true,value:p=>p.projects.size},
 {key:'days',label:'Días con registros',numeric:true,value:p=>p.recordedDays.size},
 {label:'Distribución',value:p=>p.name,cell:personMix},
 {label:'Perfil',value:p=>p.name,cell:p=>`<button class="button small" data-action="person" data-value="${esc(p.person)}">Explorar ${icon('right',12)}</button>`}
 ],{defaultSort:'name',descending:false,pageSize:15});
 const groups=groupFacts(m.facts,'discipline');
 return `<div class="tm-page"><section class="tm-directory-intro"><div><span class="tm-eyebrow">PERSONAS / HISTORIAL DE DEDICACIÓN</span><h2>Un equipo. Muchas contribuciones.</h2><p>Explora dónde registró sus horas cada colaborador en el período seleccionado.</p></div><div class="tm-directory-numbers"><div><strong>${m.activePeople}<small> / ${m.headcount}</small></strong><span>personas con registros / en fuente</span></div><div><strong>${hrs(m.total,1)}</strong><span>horas registradas del contexto</span></div></div></section><div class="tm-discipline-ribbon">${groups.map(g=>`<button ${filterAttrs('discipline',g.key)}><span>${esc(g.key)}</span><strong>${new Set(g.records.map(r=>r.person)).size}<small> personas</small></strong><em>${hrs(g.hours,0)}</em></button>`).join('')||'<span>No hay registros en este contexto.</span>'}</div><section class="tm-directory"><div class="pt-panel-heading"><div><h3>Directorio del equipo</h3><p>Busca por nombre, rol o disciplina y abre el historial individual.</p></div><div class="tm-mix-legend"><span><i style="background:${COLORS.project}"></i>Proyecto</span><span><i style="background:${COLORS.oh}"></i>OH</span><span><i style="background:${COLORS.absence}"></i>Ausencias</span><span><i style="background:${COLORS.unknown}"></i>Sin clasificar</span></div></div>${roster}</section><p class="pt-footnote">Días con registros cuenta fechas distintas, no días laborables. La distribución representa horas positivas; los totales conservan los ajustes negativos. Estas cifras describen dedicación, no desempeño individual.</p></div>`;
 }
 const projects=groupFacts(m.facts.filter(r=>r.type==='Proyecto'),'projectKey'),categories=groupFacts(m.facts,'category'),absence=sum(m.facts.filter(r=>r.type==='Ausencia'),r=>r.hours),dates=[...one.recordedDays].sort();
 return `<div class="tm-page"><div class="tm-profile-nav"><button data-action="clear-person">${icon('users',14)}Volver al directorio</button><span>${esc(pageContext())}</span></div><div class="tm-profile-layout"><aside class="tm-profile-identity person-profile"><div class="tm-avatar large">${esc(initials(one.name))}</div><span class="tm-eyebrow">HISTORIAL INDIVIDUAL</span><h2>${esc(one.name)}</h2><p>${esc(one.role)}</p><dl><div><dt>Disciplina</dt><dd>${esc(one.discipline)}</dd></div><div><dt>ID empleado</dt><dd>${esc(one.employeeId||'No registrado')}</dd></div><div><dt>Proyectos</dt><dd>${one.projects.size}</dd></div><div><dt>Días con registros</dt><dd>${one.recordedDays.size}</dd></div><div><dt>Primera / última fecha</dt><dd>${dates.length?dateLabel(dates[0])+' / '+dateLabel(dates.at(-1)):'Sin registros'}</dd></div></dl><div class="tm-profile-total"><span>Total registrado</span><strong>${hrs(one.total,1)}</strong>${personMix(one)}</div><p class="tm-profile-note">El perfil conserva los filtros de proyecto, actividad y período que tengas seleccionados.</p></aside>
 <div class="tm-profile-content"><section class="tm-hours"><div><span>Proyecto</span><strong>${hrs(one.project,1)}</strong></div><div><span>Overhead</span><strong>${hrs(one.oh,1)}</strong></div><div><span>Ausencias</span><strong>${hrs(absence,1)}</strong></div><div><span>Sin clasificar</span><strong>${hrs(one.unknown,1)}</strong></div></section><section class="tm-panel"><div class="pt-panel-heading"><div><h3>Su dedicación en el tiempo</h3><p>Proyecto y OH registrados dentro del contexto</p></div>${grainControl()}</div>${trendChart(trend(m,state.grain),{grain:state.grain,series:state.series})}</section><div class="tm-profile-pair"><section class="tm-panel"><div class="pt-panel-heading"><div><h3>Proyectos en los que participó</h3><p>Selecciona un proyecto para abrir su detalle</p></div></div>${projects.map(g=>`<button class="tm-project-entry" data-action="project-detail" data-value="${esc(g.key)}"><span><strong>${esc(g.records[0].project)}</strong><small>${esc(g.records[0].code||'Sin código')}</small></span><b>${hrs(g.hours,1)}</b>${icon('right',12)}</button>`).join('')||emptyChart('No hay horas de proyecto en este contexto.')}</section><section class="tm-panel"><div class="pt-panel-heading"><div><h3>Actividades registradas</h3><p>Categorías declaradas en el Excel</p></div></div>${hbars(categories.map(g=>({key:g.key,label:g.key,value:g.hours})),{key:'category',limit:7,color:'#578b7e'})}</section></div><section class="tm-panel"><div class="pt-panel-heading"><div><h3>En qué se registró su Overhead</h3><p>Categorías del catálogo ME&I</p></div></div>${hbars(groupFacts(m.facts.filter(r=>r.type==='Overhead'),'ohGroup').map(g=>({key:g.key,label:g.key,value:g.hours,color:OH_COLORS[OH_GROUPS.indexOf(g.key)]})),{key:'ohGroup',limit:6})}</section><section class="tm-panel tm-records"><div class="pt-panel-heading"><div><h3>Registros del colaborador</h3><p>Task, comentarios y acceso a la hoja y celda original.</p></div></div>${recordsTable(m.facts,'person-facts')}</section></div></div><p class="pt-footnote">La dedicación histórica se interpreta según el rol y las actividades registradas. Las horas por sí solas no miden productividad ni desempeño.</p></div>`;
}

function workPage(){const m=state.model,groups=groupFacts(m.facts,'category'),meeting=sum(m.facts.filter(f=>/REUNION/.test(norm(f.category))),f=>f.hours),rework=sum(m.facts.filter(f=>/REPROCESO/.test(norm(f.category))),f=>f.hours),subcategories=groupFacts(m.facts,r=>r.subcategory||'Sin subcategoría');
  const disciplines=[...new Set(m.facts.map(r=>r.discipline))].sort().map(d=>({key:d,label:d})),matrixRows=groups.slice(0,10).map(g=>({key:g.key,label:g.key}));
  return kpiGrid([kpi('Horas registradas',num(m.total,0),{unit:'h',glyph:'clock',note:'Proyecto, OH, ausencias y sin clasificar'}),kpi('Categorías de trabajo',num(groups.length),{glyph:'work',note:`${num(subcategories.length)} subcategorías presentes`}),kpi('Reuniones / comités',num(meeting,0),{unit:'h',glyph:'users',tone:'teal',note:`${pct(ratio(meeting,m.total))} de las horas registradas`}),kpi('Reproceso reportado',num(rework,0),{unit:'h',glyph:'reset',tone:'orange',note:`${pct(ratio(rework,m.total))} según categoría del Excel`})])+`<div class="grid equal">${card('Composición del trabajo','Categoría declarada en el archivo de seguimiento',hbars(groups.map(g=>({key:g.key,label:g.key,value:g.hours})),{key:'category',limit:10,color:COLORS.available}))}${card('Actividades y disciplinas','Horas por categoría · haz clic para filtrar',matrix(matrixRows,disciplines,(r,c)=>sum(m.facts.filter(f=>f.category===r.key&&f.discipline===c.key),f=>f.hours),{rowAction:'category'}))}</div><div class="grid equal">${card('Subcategorías con mayor demanda','Descripción detallada del trabajo registrado',hbars(subcategories.map(g=>({key:g.key,label:g.key,value:g.hours,action:`data-action="subcat-detail" data-value="${esc(g.key)}"`})),{limit:8,color:'#5e899b'}))}${card('Tiempo por tipo de asignación','Las ausencias se muestran aparte de la carga de trabajo',donut(TYPES.map((t,i)=>({key:t,label:t,value:[m.project,m.oh,m.absence,m.unknown][i],color:[COLORS.project,COLORS.oh,COLORS.absence,COLORS.unknown][i]}))))}</div><section class="card"><div class="card-header"><div><h2 class="card-title">Explorador de registros</h2><p class="card-subtitle">Busca conceptos, abre la fuente y exporta los registros del contexto.</p></div><button class="button small" data-action="export-detail">${icon('download',12)}CSV del contexto</button></div>${recordsTable()}</section>`;
}

function qualityPage(){const m=state.model,d=state.dataset;
  const flagged=Object.entries(FLAG_NAMES).map(([flag,label])=>({flag:Number(flag),label,count:m.facts.filter(r=>r.flags&Number(flag)).length,hours:sum(m.facts.filter(r=>r.flags&Number(flag)),r=>r.hours)}));
  const sourceRows=d.sourceSheets.map(s=>({...s,retained:d.records.filter(r=>r.source===s.name).length,retainedHours:sum(d.records.filter(r=>r.source===s.name),r=>r.hours)}));
  const unknownFacts=m.facts.filter(r=>r.flags);
  const allFuture=d.records.filter(r=>r.date>state.settings.cutoff);
  const sourceTable=table('sources',sourceRows,[{key:'name',label:'Hoja',value:r=>r.name,cell:r=>`<span class="cell-name">${esc(r.name)}</span><small class="cell-secondary">${r.state==='hidden'?'Oculta en Excel · incluida':'Visible en Excel'}</small>`},{key:'people',label:'Personas',numeric:true,value:r=>r.people},{key:'rows',label:'Filas de asignación',numeric:true,value:r=>r.rows},{key:'retained',label:'Celdas consolidadas',numeric:true,value:r=>r.retained,cell:r=>num(r.retained)},{key:'retainedHours',label:'Horas consolidadas',numeric:true,value:r=>r.retainedHours,cell:r=>num(r.retainedHours,2)},{label:'Fechas con horas',value:r=>r.first,cell:r=>r.first?`${dateLabel(r.first)} – ${dateLabel(r.last)}`:'Sin horas'}],{search:false,defaultSort:'name',descending:false});
  const dateIssues=d.issues.map(i=>`<tr><td>${esc(i.sheet)}<small class="cell-secondary">${esc(i.cell)}</small></td><td>${esc(i.original)}</td><td>${esc(i.resolved)}</td><td style="white-space:normal;min-width:210px">${esc(i.message)}</td></tr>`).join('');
  return kpiGrid([kpi('Completitud de campos',pct(m.completeness),{glyph:'quality',note:'Celdas de horas con todos los campos clave'}),kpi('Horas sin proyecto / OH',num(m.unknown,0),{unit:'h',glyph:'warning',tone:'orange',note:'Incluidas en total; excluidas de Proyecto y OH'}),kpi('Encabezados revisados',num(d.issues.length),{glyph:'calendar',tone:'orange',note:'Controles estructurales de todo el archivo'}),kpi('Registros con alertas',num(unknownFacts.length),{glyph:'file',tone:'red',note:`De ${num(m.facts.length)} registros en el contexto`})])+`<div class="grid equal">${card('Campos y clasificaciones por revisar','Una celda de horas puede presentar varias alertas.',flagged.filter(f=>f.count>0).map(f=>`<button class="quality-row" data-action="quality-filter" data-value="${f.flag}"><span class="quality-icon">${icon('warning',13)}</span><span>${esc(f.label)}</span><b>${num(f.count)}<small>${hrs(f.hours,1)}</small></b>${icon('right',12)}</button>`).join('')||'<div class="callout">Los campos clave están completos dentro de este contexto.</div>',{footer:'<span>Campos clave: persona, ID, disciplina, rol, proyecto, código cuando aplica, Task y categoría.</span>'})}${card('Controles de consolidación','Reglas aplicadas al archivo completo',`<div class="data-definition"><dt>Solapamientos diarios</dt><dd>${d.overlaps.length} fecha(s) con horas en más de una hoja</dd></div><div class="data-definition"><dt>Horas en fuente alterna</dt><dd>${hrs(d.discardedHours,2)} excluidas de la suma por solapamiento</dd></div><div class="data-definition"><dt>Posteriores al corte</dt><dd>${hrs(sum(allFuture,r=>r.hours),1)} · ${allFuture.length} registros <button class="text-link" data-action="period" data-value="future">Explorar</button></dd></div><div class="data-definition"><dt>Valores no numéricos</dt><dd>${d.invalid.length} celdas no incluidas como horas</dd></div><div class="callout warning" style="margin-top:15px;margin-bottom:0">No se interpreta una celda vacía como evidencia de disponibilidad. Las fechas posteriores al corte se señalan para revisión en la fuente, sin clasificarlas como planificación.</div>`,{tools:infoButton()})}</div><section class="card" style="margin-bottom:19px"><div class="card-header"><div><h2 class="card-title">Fuentes mensuales</h2><p class="card-subtitle">Agosto oculto está incluido. Los totales y subtotales del Excel se excluyen para evitar duplicaciones.</p></div></div>${sourceTable}</section>${d.issues.length?`<section class="card" style="margin-bottom:19px"><div class="card-header"><div><h2 class="card-title">Calendario y encabezados</h2><p class="card-subtitle">Las fechas se reconstruyen desde el primer día y se contrastan con la fila de días de semana. El archivo original se conserva.</p></div></div><div class="table-scroll" style="margin-top:14px"><table class="data-table"><thead><tr><th>Hoja / celda</th><th>Valor original</th><th>Fecha o período usado</th><th>Criterio</th></tr></thead><tbody>${dateIssues}</tbody></table></div></section>`:''}${d.overlaps.length?card('Fechas presentes en dos hojas','Se conserva una fuente completa por día, priorizando la mayor cantidad de personas con horas.',d.overlaps.map(o=>`<div class="callout"><strong>${dateLabel(o.date,{day:'numeric',month:'long',year:'numeric'})}</strong><p>Fuente utilizada: ${esc(o.selected)}. ${o.candidates.map(c=>`${esc(c.source)}: ${c.people} personas, ${hrs(c.hours,2)}`).join(' / ')}.</p><p>${hrs(o.excludedHours,2)} de la fuente alterna quedan fuera de los totales. Conviene confirmar este criterio en el Excel de origen.</p></div>`).join('')):''}<section class="card" style="margin-top:19px"><div class="card-header"><div><h2 class="card-title">Detalle de registros con alertas</h2><p class="card-subtitle">Las coincidencias repetidas se conservan y se marcan para revisión, sin borrarlas automáticamente.</p></div></div>${recordsTable(unknownFacts,'quality-facts')}</section>`;
}

function dataPage(){const d=state.dataset;return `<div class="upload-layout"><section class="card"><div class="card-header"><div><h2 class="card-title">Actualizar el seguimiento</h2><p class="card-subtitle">Carga una nueva versión del mismo formato de Excel.</p></div></div><div class="card-body"><div class="dropzone" id="dropzone"><span>${icon('upload',36)}</span><h3>Tu Excel, convertido en análisis</h3><p>Arrastra el archivo .xlsx o selecciónalo. Revisarás un resumen antes de reemplazar los datos de este navegador.</p><button class="button primary" data-action="choose-file">${icon('file',14)}Seleccionar Excel</button><small>.xlsx · máximo 30 MB · hojas mensuales FY26, FY27…</small></div><input type="file" id="file-input" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden><div class="callout" style="margin-top:17px;margin-bottom:0"><strong>Actualización en este navegador.</strong> El archivo que cargues se procesa y se guarda localmente. La publicación conserva la copia inicial; las nuevas cargas no se comparten con otros navegadores ni se sincronizan con SharePoint.</div><div class="steps"><div class="step"><div><strong>Conserva la estructura</strong>Datos de registro en A:J; fechas en fila 3; días de semana en fila 4.</div></div><div class="step"><div><strong>Incluye las hojas del período</strong>Se incorporan hojas visibles y ocultas con nombre mensual y FY.</div></div><div class="step"><div><strong>Valida los controles</strong>Revisa fechas, registros sin clasificar y los conceptos registrados.</div></div></div></div></section><div><section class="card"><div class="card-header"><div><h2 class="card-title">Archivo activo</h2><p class="card-subtitle">Copia de datos utilizada en el portal.</p></div><span class="tag green">Cargado</span></div><div class="card-body"><dl style="margin:0"><div class="data-definition"><dt>Nombre</dt><dd>${esc(state.raw.filename)}</dd></div><div class="data-definition"><dt>Hojas mensuales</dt><dd>${d.sourceSheets.length}</dd></div><div class="data-definition"><dt>Personas en histórico</dt><dd>${d.people.length}</dd></div><div class="data-definition"><dt>Registros diarios</dt><dd>${num(d.records.length)}</dd></div><div class="data-definition"><dt>Horas de todo el archivo</dt><dd>${hrs(d.hours,2)}</dd></div><div class="data-definition"><dt>Consolidación</dt><dd>${num(d.discardedRecords)} celdas de fuentes alternas excluidas por solapamiento</dd></div></dl><button class="button" style="margin-top:17px" data-action="restore-source">${icon('reset',12)}Volver a la copia inicial</button></div></section><section class="card" style="margin-top:19px"><div class="card-header"><div><h2 class="card-title">Documentación</h2><p class="card-subtitle">Definiciones y criterios para interpretar las horas.</p></div></div><div class="card-body"><div class="steps"><div class="step"><div><strong>Guía del portal</strong>Incluye las fórmulas, el tratamiento de fechas y el alcance histórico del análisis.</div></div></div><button class="button" data-action="method">${icon('help',13)}Ver método de cálculo</button><a class="button" style="margin-top:9px" href="manual-mei.pdf" target="_blank" rel="noopener">${icon('file',13)}Abrir manual adjunto</a></div></section></div></div>`;}

function showModal(title,subtitle,content,footer='',wide=false){
  if(!state.modal)modalReturnFocus=document.activeElement;
  app.inert=true;document.body.style.overflow='hidden';
  overlay.innerHTML=`<div class="modal-backdrop" data-close-modal="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Cerrar ventana">${icon('close',18)}</button></header><div class="modal-content">${content}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;
  const first=overlay.querySelector('button,input,select,a[href]');first?.focus();
}
function closeModal(){state.modal=null;state.pendingImport=null;overlay.innerHTML='';app.inert=false;document.body.style.overflow='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});else document.getElementById('main')?.focus({preventScroll:true});}
function ohCatalogTable(){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Task category</th><th>Task number</th><th>Task</th></tr></thead><tbody>${Object.values(OH_TASK_CATALOG).map(t=>`<tr><td>${esc(t.group)}</td><td>${t.code}</td><td>${esc(t.name)}</td></tr>`).join('')}</tbody></table></div>`;}
function openMethod(){
  showModal('Guía de interpretación','Definiciones históricas y reglas de consolidación del portal.',`<div class="methodology"><h3>Análisis histórico de horas</h3><p>La fuente contiene horas ya registradas en el sistema. El portal analiza dónde se registró el tiempo. No deduce disponibilidad, sobrecarga, productividad ni planificación.</p><table><thead><tr><th>Indicador</th><th>Definición</th></tr></thead><tbody><tr><td>Horas registradas</td><td>Proyecto + OH + ausencias + sin clasificar.</td></tr><tr><td>Participación de proyecto</td><td>Proyecto / total registrado del contexto.</td></tr><tr><td>OH Mix</td><td>OH / (Proyecto + OH). Excluye ausencias y horas sin clasificar.</td></tr><tr><td>OH sobre total registrado</td><td>OH / total registrado, incluidas ausencias y sin clasificar.</td></tr><tr><td>Variación mensual</td><td>Horas del mes − horas del mes anterior disponible. Variación % = diferencia / horas anteriores; s/d si la base es cero o no existe.</td></tr><tr><td>Completitud de campos</td><td>Registros diarios con campos clave completos / registros del contexto. No mide horas pendientes de cargar.</td></tr></tbody></table><h3>Filtros y períodos</h3><p>Los filtros delimitan los registros y recalculan los porcentajes a partir de sus sumas. La comparación mensual conserva filtros de trabajo y personas, pero ignora los filtros temporales y el corte para mostrar todos los meses disponibles. Presenta fechas y días con registros; no certifica meses cerrados ni ajusta por calendario laboral. Una celda vacía no confirma disponibilidad.</p><p>Los recuentos de registros corresponden a celdas diarias de horas, no a filas del Excel. Los porcentajes con denominador cero se muestran como s/d.</p><h3>Tratamiento de fechas y solapamientos</h3><ul><li>Se incluyen todas las hojas mensuales reconocidas, aunque estén ocultas. Se excluyen filas «Total» y columnas «Tot.».</li><li>Las fechas se reconstruyen en secuencia desde el primer encabezado de cada hoja y se contrastan con los días de semana. Las diferencias se muestran en Calidad de datos.</li><li>Las horas de los días de inicio o fin de otro mes conservan su fecha real. Por ejemplo, los primeros días de octubre pueden estar en septiembre.</li><li>Cuando dos hojas tienen horas en la misma fecha, se elige una fuente diaria completa con más personas que registraron horas. En empate se prioriza la hoja del mes calendario. No se suman ambas fuentes. Las fuentes alternas y sus horas excluidas están documentadas.</li><li>Los posibles repetidos dentro de una hoja se marcan para revisión y se conservan.</li><li>La fecha de corte actual es ${dateLabel(state.settings.cutoff,{day:'numeric',month:'long',year:'numeric'})}. Puedes incluir fechas posteriores de forma explícita. Los registros posteriores al corte se señalan para revisión de fechas.</li></ul><h3>Proyecto, OH, ausencias y horas sin clasificar</h3><p>Las ausencias se reconocen por el código 01511001 o por conceptos de festivos, vacaciones, incapacidades, licencias, cumpleaños y examen médico. El OH se identifica por los códigos y conceptos del catálogo, incluidos formación interna, AI4E, propuestas y COPASS. Los registros sin proyecto reconocible se muestran como «Sin clasificar» y no se agregan a Proyecto ni a OH.</p><h3>Catálogo de Tasks aportado por el equipo</h3><p>Las cinco categorías oficiales son General Expenses, Bidding, Training, Other OH y Non-productive. «Sin clasificar» es un control de calidad adicional para códigos que no figuran en el catálogo, no una sexta categoría oficial. La categoría se asigna por número de Task, no por inferencias a partir del nombre del proyecto.</p>${ohCatalogTable()}<p>4.02 Colombia Hypercare se clasifica como Other OH. Si el texto del seguimiento difiere, se conserva para trazabilidad; no cambia la categoría del catálogo. Las Tasks 3.04 y 3.05 pertenecen a Training, y Graduates (4.01) pertenece a Other OH.</p><h3>Datos compartidos y actualización</h3><p>Esta versión es de acceso público. Todos los visitantes acceden a la misma copia inicial de los datos incluida en la publicación. «Actualizar Excel» lee una nueva copia en el navegador y la conserva localmente; no envía el archivo a SharePoint ni lo sincroniza con otros equipos. Puedes exportar el contexto como CSV o imprimir la vista actual.</p></div>`,`<span>ME&I Resource & OH Intelligence</span><button class="button primary" data-action="close-modal">Entendido</button>`,true);
  state.modal='method';
}
function openSettings(tab='schedule',keep=false){
  if(!keep)state.settingsDraft=structuredClone(state.settings);
  state.settingsTab=tab;const draft=state.settingsDraft;
  let body='';
  if(tab==='schedule')body=`<div class="settings-group"><h3>Fecha de corte para revisión</h3><p>Permite acotar el análisis histórico y señalar registros con fechas posteriores. No convierte estos registros en planificación ni modifica el Excel.</p><input class="date-input" style="max-width:230px" type="date" id="settings-cutoff" value="${esc(draft.cutoff)}"></div><div class="callout">Los indicadores se calculan sobre las horas registradas. No se utiliza una jornada supuesta para evaluar a las personas.</div>`;
  else {
    const groups=groupFacts(state.dataset.records.filter(r=>r.type==='Overhead'),r=>r.ohKey);
    const unknown=groups.filter(g=>!OH_TASK_CATALOG[g.key]);
    body=`<div class="settings-group"><h3>Catálogo oficial de categorías y Tasks</h3><p>Se aplica la tabla que compartió el equipo. Las cinco categorías se conservan en inglés para coincidir con el sistema.</p>${ohCatalogTable()}</div><div class="settings-group"><h3>Tasks fuera del catálogo</h3><p>Los códigos siguientes no aparecen en la tabla aportada. Puedes asignarlos explícitamente a una categoría; de lo contrario permanecen en «Sin clasificar».</p>${unknown.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Task</th><th>Conceptos originales</th><th>Asignación manual</th></tr></thead><tbody>${unknown.sort((a,b)=>a.key.localeCompare(b.key,'es')).map(g=>{const current=draft.overrides[g.key]||'Sin clasificar';return `<tr><td>${esc(g.records[0].task||'Sin Task')}</td><td class="cell-truncate" style="max-width:265px" title="${esc([...new Set(g.records.map(r=>r.project))].join(' · '))}">${esc([...new Set(g.records.map(r=>r.project))].slice(0,2).join(' · '))}</td><td><select class="taxonomy-select" data-oh-override="${esc(g.key)}" aria-label="Clasificar Task ${esc(g.key||'sin Task')}">${OH_GROUPS.map(n=>`<option ${n===current?'selected':''}>${n}</option>`).join('')}</select></td></tr>`;}).join('')}</tbody></table></div>`:'<p>Todas las Tasks de OH coinciden con el catálogo.</p>'}</div><div class="callout">La Task 4.02 es Colombia Hypercare y pertenece a Other OH, aunque el concepto escrito en el seguimiento difiera. Las Tasks del catálogo no se reclasifican automáticamente.</div><button class="button small" data-action="reset-oh">Quitar asignaciones manuales</button>`;
  }
  showModal('Configuración del análisis','Fecha de revisión y clasificación de las horas históricas.',`<div class="settings-tabs"><button data-action="settings-tab" data-value="schedule" class="${tab==='schedule'?'active':''}">Fecha de corte</button><button data-action="settings-tab" data-value="oh" class="${tab==='oh'?'active':''}">Catálogo de Overhead</button></div>${body}`,`<span>Se guarda en este navegador.</span><div class="actions"><button class="button" data-action="close-modal">Cancelar</button><button class="button primary" data-action="save-settings">Aplicar cambios</button></div>`,tab==='oh');
  state.modal='settings';
}
function captureSettings(){if(state.modal!=='settings')return;
  overlay.querySelectorAll('[data-schedule]').forEach(el=>state.settingsDraft.schedule[Number(el.dataset.schedule)]=Number(el.value));
  const cutoff=overlay.querySelector('#settings-cutoff');if(cutoff)state.settingsDraft.cutoff=cutoff.value;
  overlay.querySelectorAll('[data-oh-override]').forEach(el=>state.settingsDraft.overrides[el.dataset.ohOverride]=el.value);
}
function saveSettings(){captureSettings();const draft=state.settingsDraft;
  if(draft.schedule.some(v=>!Number.isFinite(v)||v<0||v>24)){toast('Cada jornada diaria debe estar entre 0 y 24 horas.',true);return;}
  if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.cutoff)){toast('Selecciona una fecha de corte válida.',true);return;}
  if(state.filters.to===state.settings.cutoff)state.filters.to=draft.cutoff;
  state.settings=draft;safeStore.set('mei-settings-v1',state.settings);rebuild(state.raw);closeModal();render();toast('Fecha de corte y clasificación aplicadas. Indicadores recalculados.');
}

function openRecord(id){const r=state.dataset.recordLookup.get(Number(id));if(!r)return;
  const fields=[['Fecha',dateLabel(r.date,{day:'numeric',month:'long',year:'numeric'})],['Colaborador',r.name],['ID empleado',r.employeeId||'No registrado'],['Disciplina / rol',r.discipline+' · '+r.role],['Proyecto / concepto',r.project],['Código de proyecto',r.code||'No registrado'],['Task',r.task||'No registrada'],['Categoría',r.category],['Subcategoría',r.subcategory||'No registrada'],['Categoría OH',r.ohGroup||'No aplica'],['Hoja',r.source],['Celda / fila',r.cell+' · fila '+r.row]];
  showModal('Trazabilidad del registro',`${hrs(r.hours,2)} · ${esc(r.source)}!${esc(r.cell)}`,`<div class="detail-badges"><span class="tag ${r.type==='Proyecto'?'green':r.type==='Overhead'?'pink':'yellow'}">${esc(r.type)}</span>${Object.entries(FLAG_NAMES).filter(([f])=>r.flags&Number(f)).map(([,label])=>`<span class="tag yellow">${esc(label)}</span>`).join('')}</div><div class="detail-grid">${fields.map(([k,v])=>`<div class="detail-field"><label>${k}</label><span>${esc(v)}</span></div>`).join('')}</div><div class="detail-note"><strong>Comentarios de la fuente</strong><p>${esc(r.comment||'Sin comentarios adicionales.')}</p></div>`,`<span>Valor de la celda diaria original.</span><button class="button primary" data-action="close-modal">Cerrar</button>`);state.modal='record';
}
function openProject(key){const p=state.model.projects.find(p=>p.key===key);if(!p)return;const facts=p.records,people=groupFacts(facts,'person'),discs=groupFacts(facts,'discipline');
  showModal(esc(p.name),`Código ${esc(p.code||'no registrado')} · ${esc(pageContext())}`,kpiGrid([kpi('Horas de proyecto',num(p.hours,1),{unit:'h',glyph:'projects'}),kpi('Personas',num(p.people),{glyph:'users'}),kpi('Participación',pct(p.share),{glyph:'target'}),kpi('Tasks',num(p.tasks),{glyph:'work'})])+`<div class="grid equal">${card('Distribución por disciplina','Horas reportadas al proyecto',hbars(discs.map(d=>({key:d.key,label:d.key,value:d.hours})),{key:'discipline'}))}${card('Participación por persona','Horas dentro del contexto seleccionado',hbars(people.map(d=>({key:d.key,label:d.records[0].name,value:d.hours,action:`data-action="person" data-value="${esc(d.key)}"`})),{limit:8,color:COLORS.available}))}</div><div style="margin-top:15px">${recordsTable(facts,'project-facts')}</div>`,`<span>El proyecto se agrupa por código y nombre.</span><button class="button primary" data-action="focus-project" data-value="${esc(key)}">Filtrar este proyecto</button>`,true);state.modal='project';state.modalProject=key;
}
function openSubcategory(value){const facts=state.model.facts.filter(r=>(r.subcategory||'Sin subcategoría')===value);showModal('Detalle de subcategoría',esc(value),recordsTable(facts,'subcategory-facts'),`<span>${hrs(sum(facts,r=>r.hours),1)} en ${facts.length} registros del contexto.</span><button class="button primary" data-action="close-modal">Cerrar</button>`,true);state.modal='subcategory';state.modalSubcategory=value;}

function qualitySupplement(){const d=state.dataset;return (d.invalid.length?`<section class="card" style="margin-top:19px"><div class="card-header"><div><h2 class="card-title">Valores no numéricos del archivo</h2><p class="card-subtitle">Se conservan como incidencias. No se convierten en horas ni en ceros.</p></div></div><div class="table-scroll" style="margin-top:14px"><table class="data-table"><thead><tr><th>Hoja</th><th>Celda</th><th>Colaborador</th><th>Valor encontrado</th></tr></thead><tbody>${d.invalid.map(r=>`<tr><td>${esc(r.source)}</td><td>${esc(r.cell)}</td><td>${esc(r.name)}</td><td><span class="tag yellow">${esc(r.value)}</span></td></tr>`).join('')}</tbody></table></div></section>`:'')+(d.excludedRecords.length?`<section class="card" style="margin-top:19px"><div class="card-header"><div><h2 class="card-title">Registros de fuentes alternas</h2><p class="card-subtitle">Estas ${d.excludedRecords.length} celdas (${hrs(d.discardedHours,2)}) se conservan para comparar las hojas; están excluidas de los KPIs.</p></div></div>${recordsTable(d.excludedRecords,'excluded-facts')}<div class="card-footer"><span>Hay diferencias de concepto y horas entre hojas; no se supone que sean duplicados idénticos. Confirma la fuente diaria elegida antes de cerrar el período.</span></div></section>`:'');}

async function loadImport(file){
  if(!file)return;if(!/\.xlsx$/i.test(file.name)){toast('Selecciona un archivo de Excel con extensión .xlsx.',true);return;}
  showModal('Leyendo el nuevo seguimiento',esc(file.name),'<div class="loading-inline"><span class="loader"></span>Consolidando hojas mensuales y verificando fechas…</div>');state.modal='import-loading';
  try{const raw=await parseWorkbook(file),dataset=buildDataset(raw,state.settings);if(state.modal!=='import-loading')return;
    if(!dataset.records.length)throw new Error('No hay celdas numéricas de horas en las hojas reconocidas. Comprueba el formato de fechas y las filas de datos.');
    state.pendingImport={raw,dataset};
    showModal('Revisar nueva versión',esc(file.name),kpiGrid([kpi('Hojas mensuales',String(dataset.sourceSheets.length),{glyph:'file'}),kpi('Personas',String(dataset.people.length),{glyph:'users'}),kpi('Registros',num(dataset.records.length),{glyph:'clock'}),kpi('Horas',num(dataset.hours,1),{glyph:'capacity',unit:'h'})])+`<div class="callout">Se reemplazará la copia activa <strong>en este navegador</strong>. Los filtros volverán al último mes anterior disponible. La publicación y otros navegadores conservarán los datos iniciales.</div><div class="data-definition"><dt>Hojas incluidas</dt><dd>${dataset.sourceSheets.map(s=>esc(s.name)+(s.state==='hidden'?' (oculta)':'')).join('<br>')}</dd></div><div class="data-definition"><dt>Controles de calendario</dt><dd>${dataset.issues.length} encabezados para revisar</dd></div><div class="data-definition"><dt>Solapamientos</dt><dd>${dataset.overlaps.length} fechas · ${hrs(dataset.discardedHours,2)} de fuentes alternas excluidas</dd></div><div class="data-definition"><dt>Celdas no numéricas</dt><dd>${dataset.invalid.length} sin incluir en horas</dd></div>`,`<span>El Excel original no se modifica.</span><div class="actions"><button class="button" data-action="close-modal">Cancelar</button><button class="button primary" data-action="apply-import">Usar esta versión</button></div>`,true);state.modal='import-review';
  }catch(error){closeModal();toast(error.message||'No se pudo leer este Excel.',true);}
}
async function applyImport(){const pending=state.pendingImport;if(!pending)return;const raw=pending.raw;
  state.raw=raw;state.dataset=pending.dataset;state.filters=defaultFilters(state.dataset);state.filters.to=state.settings.cutoff;state.usingLocal=true;state.tables={};state.view='overview';closeModal();render();location.hash='overview';
  try{await localSource('set',raw);toast('Nueva versión cargada y guardada en este navegador.');}catch{toast('Datos cargados para esta sesión. El navegador no permitió guardarlos localmente.',true);}
}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportDetail(){const rows=[['Fecha','Semana del lunes','Mes calendario','FY fuente','Colaborador','ID empleado','Disciplina','Rol','Tipo de hora','Categoría OH','Proyecto / concepto','Código proyecto','Task','Categoría','Subcategoría','Comentarios','Horas','Hoja origen','Celda','Alertas','Archivo fuente'],...state.model.facts.map(r=>[r.date,r.week,r.month,r.fy,r.name,r.employeeId,r.discipline,r.role,r.type,r.ohGroup,r.project,r.code,r.task,r.category,r.subcategory,r.comment,num(r.hours,2),r.source,r.cell,Object.entries(FLAG_NAMES).filter(([f])=>r.flags&Number(f)).map(([,l])=>l).join(' | '),state.raw.filename])];download('MEI_detalle_'+APP_DATE+'.csv',csvText(rows));toast(`${num(state.model.facts.length)} registros exportados con trazabilidad.`);}
